import traceback
import urllib.request
from datetime import datetime, UTC
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse

def _palaver_find_runtime_root():
    current = Path(__file__).resolve()
    for parent in [current.parent, *current.parents]:
        if (parent / "runtime").exists() and (parent / "vault").exists():
            return parent
    return Path.home() / "savant-runtime"


def _palaver_find_runtime_root():
    current = Path(__file__).resolve()
    for parent in [current.parent, *current.parents]:
        if (parent / "runtime").exists() and (parent / "vault").exists():
            return parent
    return Path.home() / "savant-runtime"


# PALAVER_DOTENV_DIRECT_LOAD_START
def _palaver_load_env_file():
    import os
    from pathlib import Path

    root = _palaver_find_runtime_root()
    env = root / ".env"

    if not env.exists():
        return

    for raw in env.read_text(encoding="utf-8", errors="replace").splitlines():
        line = raw.strip()

        if not line or line.startswith("#") or "=" not in line:
            continue

        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip().strip('"').strip("'")

        if key and key not in os.environ:
            os.environ[key] = value

_palaver_load_env_file()
# PALAVER_DOTENV_DIRECT_LOAD_END

ROOT = _palaver_find_runtime_root()


RUNTIME = ROOT / "runtime"
PORT = int(os.getenv("PALAVER_WEB_PORT", "8787"))
sys.path.insert(0, str(RUNTIME))


def load_env():
    env = ROOT / ".env"
    if not env.exists():
        return
    for line in env.read_text(encoding="utf-8", errors="ignore").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        os.environ.setdefault(k.strip(), v.strip().strip('"').strip("'"))


load_env()

try:
