.brandText p{margin:7px 0 0;font-size:12px;letter-spacing:.08em;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nav{position:relative;display:flex;gap:6px;padding:6px;border:1px solid var(--line);border-radius:999px;background:rgba(5,6,9,.42)}
.nav button{width:auto;margin:0;border:0;border-radius:999px;background:transparent;color:var(--muted);padding:10px 14px;font-size:12px;font-weight:800;letter-spacing:.04em}
.nav button.active,.nav button:hover{background:var(--white);color:#050609;box-shadow:0 0 34px rgba(255,255,255,.16)}
.status{justify-self:end;display:flex;align-items:center;gap:9px;font-size:12px;color:var(--soft);padding:10px 13px;border:1px solid rgba(255,47,157,.35);background:rgba(255,47,157,.10);border-radius:999px;position:relative}
.dot{width:9px;height:9px;border-radius:50%;background:var(--acid);box-shadow:0 0 22px var(--acid);animation:pulse 2.8s ease-in-out infinite}
.shell{min-height:0;display:grid;grid-template-columns:320px minmax(0,1fr) 380px;gap:16px}
.card{min-height:0;border:1px solid var(--line);border-radius:34px;background:linear-gradient(145deg,rgba(17,21,28,.72),rgba(5,6,9,.50));backdrop-filter:var(--blur);box-shadow:0 34px 120px rgba(0,0,0,.44),inset 0 1px 0 rgba(255,255,255,.06);overflow:hidden;display:flex;flex-direction:column;animation:rise .55s ease both}
.cardHead{padding:18px 18px 15px;display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid var(--line);background:linear-gradient(90deg,rgba(255,255,255,.055),rgba(255,255,255,.01))}
.cardHead b{font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:var(--white)}
.cardHead span{font-size:11px;letter-spacing:.10em;color:var(--gold);text-transform:uppercase}
.cardBody{padding:16px;overflow:auto;min-height:0}
.heroText{font-family:Georgia,serif;font-size:32px;line-height:1.02;letter-spacing:-.05em;color:var(--cream);margin:0 0 14px}
.heroText em{font-style:normal;color:var(--pink)}
.kicker{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);margin-bottom:10px}
.cmds{display:grid;gap:9px}
button{cursor:pointer;font:inherit;border:1px solid var(--line);border-radius:18px;background:rgba(255,255,255,.055);color:var(--soft);padding:13px 14px;transition:.18s ease}
button:hover{transform:translateY(-1px);border-color:rgba(255,255,255,.28);background:rgba(255,255,255,.10)}
button.primary{background:var(--white);color:#050609;font-weight:900}
button.accent{background:linear-gradient(135deg,var(--pink),var(--pink2));border-color:rgba(255,47,157,.55);color:var(--white);font-weight:900}
.stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px}
.stat{border:1px solid var(--line);border-radius:22px;padding:14px;background:rgba(255,255,255,.04)}
.stat .k{font-size:10px;color:var(--muted);letter-spacing:.15em;text-transform:uppercase}
.stat .v{font-size:24px;font-weight:950;color:var(--cream);margin-top:4px}
#chat{flex:1;padding:24px;overflow:auto;display:flex;flex-direction:column;gap:22px;scroll-behavior:smooth}
.msg{max-width:84%;border-radius:30px;overflow:hidden;white-space:pre-wrap;line-height:1.58;box-shadow:0 32px 70px rgba(0,0,0,.38);animation:rise .34s ease both;position:relative}
.msg:after{content:"";position:absolute;inset:0;background:linear-gradient(120deg,rgba(255,255,255,.16),transparent 28%,transparent);pointer-events:none}
.user{align-self:flex-end;background:linear-gradient(135deg,var(--gold),var(--gold2));border:1px solid rgba(214,180,95,.62)}
.assistant{align-self:flex-start;background:linear-gradient(135deg,var(--pink),var(--pink2));border:1px solid rgba(255,47,157,.62)}
.msgHeader{padding:14px 17px 0;font-size:11px;font-weight:1000;letter-spacing:.18em;text-transform:uppercase;position:relative;z-index:1}
.user .msgHeader{color:var(--pink)}
.assistant .msgHeader{color:var(--cream)}
.msgBody{padding:12px 17px 17px;color:#fff;font-size:15px;position:relative;z-index:1}
.composer{border-top:1px solid var(--line);background:rgba(5,6,9,.62);padding:14px;display:grid;grid-template-columns:1fr auto auto;gap:10px}
textarea,input{width:100%;background:rgba(5,6,9,.86);color:#fff;border:1px solid var(--line2);border-radius:22px;padding:15px;font:inherit;outline:none}
textarea:focus,input:focus{border-color:var(--cream);box-shadow:0 0 0 5px rgba(214,180,95,.10)}
#input{resize:none;min-height:58px;max-height:180px}
.iconBtn{width:58px;border-radius:22px;font-size:18px;font-weight:1000;padding:0}
#trace,#patchOut,#fileTree{white-space:pre-wrap;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px;line-height:1.5;color:var(--muted)}
.traceBox{border:1px solid var(--line);border-radius:22px;padding:14px;background:rgba(5,6,9,.35)}
.patchTools{display:grid;gap:10px}
.treeItem{padding:7px 9px;border-radius:10px;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.treeItem:hover{background:rgba(255,255,255,.08);color:var(--cream)}
.treeDir{color:var(--gold)}
.treeFile{color:var(--muted)}
#graphCanvas{width:100%;height:260px;border:1px solid var(--line);border-radius:22px;background:#050609}
.timeline{display:grid;gap:8px}
.timelineItem{padding:10px;border-radius:14px;background:rgba(255,255,255,.04);border:1px solid var(--line)}
.timelineTime{font-size:10px;color:var(--gold);letter-spacing:.12em;text-transform:uppercase;margin-bottom:4px}
.timelineText{font-size:12px;color:var(--soft)}
.drawer{position:fixed;inset:16px;z-index:20;display:none;place-items:center;background:rgba(5,6,9,.66);backdrop-filter:blur(30px)}
.drawer.open{display:grid}
.palette{width:min(860px,94vw);border:1px solid rgba(255,255,255,.2);border-radius:36px;background:linear-gradient(145deg,rgba(17,21,28,.94),rgba(5,6,9,.86));box-shadow:0 40px 160px rgba(0,0,0,.65);padding:20px}
.palette input{font-size:24px;border-radius:26px;margin-bottom:14px}
.quick{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.editorPanel{position:fixed;right:16px;bottom:16px;width:min(920px,calc(100vw - 32px));height:min(680px,calc(100vh - 32px));z-index:30;display:none;border:1px solid rgba(255,255,255,.2);border-radius:30px;background:rgba(5,6,9,.88);backdrop-filter:blur(30px);box-shadow:0 40px 160px rgba(0,0,0,.68);overflow:hidden}
.editorPanel.open{display:flex;flex-direction:column}
.editorTop{padding:14px 16px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line)}
.editorTop b{color:var(--cream)}
#editorContent{flex:1;margin:0;padding:18px;overflow:auto;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:13px;line-height:1.5;color:var(--soft);white-space:pre}
/* PALAVER_PERSONA_SELECTOR_V1 */
.conversationHead{gap:12px}
.personaCtl{display:flex;align-items:center;gap:8px;min-width:0}
.personaCtl label{font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.personaCtl select{max-width:220px;min-width:150px;padding:7px 28px 7px 10px;border-radius:12px;border:1px solid var(--line);background:#0b0d11;color:var(--cream);font:inherit;font-size:11px;outline:none}
.personaCtl select:focus{border-color:rgba(214,180,95,.62)}
.personaCtl select:disabled{opacity:.55}
.personaMeta{font-size:9px;color:var(--muted);white-space:nowrap}
@media(max-width:1180px){html,body{overflow:auto}.app{height:auto;min-height:100vh}.top{height:auto;grid-template-columns:1fr;gap:12px}.status{justify-self:start}.nav{width:100%;overflow:auto;justify-content:flex-start}.shell{grid-template-columns:1fr}.card{min-height:320px}#chat{min-height:58vh}.msg{max-width:100%}.composer{grid-template-columns:1fr auto}.quick{grid-template-columns:1fr}.personaCtl{flex-wrap:wrap}.personaCtl select{max-width:100%}}
</style>
</head>
<body>
<div class="bg"></div><div class="noise"></div>

<div class="drawer" id="drawer" onclick="if(event.target.id==='drawer')togglePalette(false)">
  <div class="palette">
    <input id="paletteInput" placeholder="Command palette — ask, inspect, build, patch" onkeydown="if(event.key==='Enter')runPalette()">
    <div class="quick">
      <button onclick="paletteRun('health')">Health</button>
      <button onclick="paletteRun('files')">Files</button>
      <button onclick="paletteRun('graph')">Graph</button>
      <button onclick="paletteRun('patches')">Patches</button>
      <button onclick="paletteRun('file read runtime/core.py')">Read core</button>
      <button onclick="paletteRun('repository report')">Repository report</button>
    </div>
  </div>
</div>

<div class="editorPanel" id="editorPanel">
  <div class="editorTop">
    <b id="editorTitle">file</b>
    <div>
      <button onclick="fill('file read '+currentFile);closeEditor()">Ask with file</button>
      <button onclick="closeEditor()">Close</button>
    </div>
  </div>
  <pre id="editorContent"></pre>
</div>

<div class="app">
<header class="top">
  <div class="brand"><div class="logo">§</div><div class="brandText"><h1>PALAVER</h1><p>persistent AI workstation / runtime builder / server cockpit</p></div></div>
  <nav class="nav">
    <button class="active" onclick="focusChat()">Chat</button>
    <button onclick="send('files')">Files</button>
    <button onclick="send('graph')">Graph</button>
    <button onclick="send('patches')">Patches</button>
    <button onclick="togglePalette(true)">Palette</button>
  </nav>
  <div class="status" id="status"><span class="dot"></span><span>online</span></div>
</header>

<section class="shell">
<aside class="card">
  <div class="cardHead"><b>Command rail</b><span>runtime</span></div>
  <div class="cardBody">
    <div class="kicker">Build from inside the server</div>
    <h2 class="heroText">Capital with <em>memory</em>. Code with consequence.</h2>
    <div class="cmds">
      <button class="primary" onclick="send('health')">Health</button>
      <button onclick="send('diag')">Diagnostics</button>
      <button onclick="send('files')">Files</button>
      <button onclick="send('graph')">Graph</button>
      <button onclick="send('patches')">Patches</button>
      <button onclick="send('rebuild')">Rebuild</button>
      <button onclick="fill('file read runtime/core.py')">Read core.py</button>
      <button onclick="fill('search authority')">Search authority</button>
      <button onclick="fill('retrieve message registry')">Retrieve memory</button>
      <button onclick="loadTree()">Load file tree</button>
      <button onclick="loadGraph()">Graph explorer</button>
      <button onclick="loadTimeline()">Activity timeline</button>
    </div>
    <div class="stats">
      <div class="stat"><div class="k">mode</div><div class="v">AI</div></div>
      <div class="stat"><div class="k">vault</div><div class="v">ON</div></div>
      <div class="stat"><div class="k">patch</div><div class="v">SAFE</div></div>
      <div class="stat"><div class="k">graph</div><div class="v">LIVE</div></div>
    </div>
    <br>
    <div id="fileTree"></div>
  </div>
</aside>

<main class="card">
  <div class="cardHead conversationHead">
    <b>Conversation</b>
    <div class="personaCtl">
      <label for="personaSelect">Persona</label>
      <select id="personaSelect" onchange="setPersonaPreference(this.value)" disabled>
        <option value="">Orobouros · default</option>
      </select>
      <span class="personaMeta" id="personaMeta">loading</span>
    </div>
  </div>
  <div id="chat"><div class="msg assistant"><div class="msgHeader">PALAVER</div><div class="msgBody">Run health first. Then ask naturally. Use Ctrl+K for the command palette.</div></div></div>
  <div class="composer">
    <textarea id="input" placeholder="Ask Palaver anything, or type files / graph / file read runtime/core.py" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();submitMsg()}"></textarea>
    <button class="iconBtn" onclick="togglePalette(true)">⌘</button>
    <button class="iconBtn accent" onclick="submitMsg()">➜</button>
  </div>
</main>

<aside class="card">
  <div class="cardHead"><b>Build tools</b><span>patches</span></div>
  <div class="cardBody">
    <div class="patchTools">
      <input id="patchPath" placeholder="target path">
      <textarea id="patchContent" placeholder="content to write/append"></textarea>
      <button class="accent" onclick="patchWrite()">Propose write patch</button>
      <button onclick="patchAppend()">Propose append patch</button>
    </div>
    <br><div id="patchOut" class="traceBox">Patch output appears here.</div><br>
    <canvas id="graphCanvas"></canvas><br><br>
    <div id="timeline" class="timeline"></div><br>
    <div class="cardHead" style="margin:0 -16px 12px"><b>Trace</b><span>evidence</span></div>
    <div id="trace" class="traceBox">ready</div>
  </div>
</aside>
</section>
</div>

<script>
const chat=document.getElementById("chat"),input=document.getElementById("input"),trace=document.getElementById("trace"),statusEl=document.getElementById("status"),patchOut=document.getElementById("patchOut"),drawer=document.getElementById("drawer"),paletteInput=document.getElementById("paletteInput");
let currentFile="";
function esc(s){return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function add(role,text){const el=document.createElement("div");el.className="msg "+role;el.innerHTML=`<div class="msgHeader">${role==="user"?"YOU":"PALAVER"}</div><div class="msgBody">${esc(text)}</div>`;chat.appendChild(el);el.scrollIntoView({behavior:"smooth",block:"end"})}
function fill(x){input.value=x;input.focus()}
function focusChat(){input.focus()}
function togglePalette(open){drawer.classList.toggle("open",open);if(open)setTimeout(()=>paletteInput.focus(),60)}
function runPalette(){const v=paletteInput.value.trim();if(!v)return;paletteInput.value="";togglePalette(false);send(v)}
function paletteRun(v){paletteInput.value="";togglePalette(false);send(v)}
async function loadPersonaControl(){
 const select=document.getElementById("personaSelect");
 const meta=document.getElementById("personaMeta");
 if(!select||!meta)return;
 try{
  const [personasRes,prefRes]=await Promise.all([
   fetch("/api/personas"),
   fetch("/api/persona/preference")
  ]);
  const personasData=await personasRes.json();
  const prefData=await prefRes.json();
  if(!personasData.ok)throw new Error(personasData.error||"persona discovery failed");
  if(!prefData.ok)throw new Error(prefData.error||"persona preference failed");

  const defaultId=personasData.default_persona||prefData.default_persona||"orobouros";
  const workspaceId=prefData.workspace_persona||"";
  const rows=Array.isArray(personasData.personas)?personasData.personas:[];

  select.innerHTML="";

  const defaultOption=document.createElement("option");
  defaultOption.value="";
  defaultOption.textContent=(rows.find(x=>x.persona_id===defaultId)?.display_name||"Orobouros")+" · default";
  select.appendChild(defaultOption);

  for(const persona of rows){
   if(!persona||persona.persona_id===defaultId)continue;
   const option=document.createElement("option");
   option.value=persona.persona_id;
   option.textContent=persona.display_name||persona.persona_id;
   select.appendChild(option);
  }

  select.value=(workspaceId&&workspaceId!==defaultId)?workspaceId:"";
  meta.textContent=workspaceId?"workspace":"default";
  select.disabled=false;
 }catch(error){
  select.disabled=true;
  meta.textContent="unavailable";
  trace.textContent="persona UI: "+String(error);
 }
}

async function setPersonaPreference(value){
 const select=document.getElementById("personaSelect");
 const meta=document.getElementById("personaMeta");
 if(!select||!meta)return;

 select.disabled=true;
 meta.textContent="saving";

 try{
  const response=await fetch(
   "/api/persona/preference",
   {
    method:"POST",
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify({
     persona_id:value||null
    })
   }
  );

  const data=await response.json();

  if(!data.ok){
   throw new Error(data.error||"persona preference save failed");
  }

  const defaultId=data.default_persona||"orobouros";
  const workspaceId=data.workspace_persona||"";

  select.value=(workspaceId&&workspaceId!==defaultId)?workspaceId:"";
  meta.textContent=workspaceId?"workspace":"default";
  trace.textContent="persona: "+(data.effective_persona||defaultId);
 }catch(error){
  meta.textContent="error";
  trace.textContent="persona preference: "+String(error);
  await loadPersonaControl();
 }finally{
  select.disabled=false;
 }
}

async function submitMsg(){const m=input.value.trim();if(!m)return;input.value="";await send(m)}
async function send(message){add("user",message);statusEl.innerHTML='<span class="dot"></span><span>thinking</span>';trace.textContent="running";try{const res=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message})});const data=await res.json();add("assistant",data.answer||"(empty response)");trace.textContent=data.trace||""}catch(e){add("assistant","Browser/API error: "+e);trace.textContent=String(e)}statusEl.innerHTML='<span class="dot"></span><span>online</span>'}
async function patchWrite(){const path=document.getElementById("patchPath").value.trim(),content=document.getElementById("patchContent").value;const res=await fetch("/api/patch/write",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({path,content,intent:"browser write proposal"})});const data=await res.json();patchOut.textContent=data.output||JSON.stringify(data,null,2)}
async function patchAppend(){const path=document.getElementById("patchPath").value.trim(),content=document.getElementById("patchContent").value;const res=await fetch("/api/patch/append",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({path,content,intent:"browser append proposal"})});const data=await res.json();patchOut.textContent=data.output||JSON.stringify(data,null,2)}
async function loadTree(path=""){
 try{
  const res=await fetch("/api/tree?path="+encodeURIComponent(path));
  const data=await res.json();
  if(!data.ok){trace.textContent=data.error||"tree failed";return}
  if(!path){
    document.getElementById("fileTree").innerHTML=renderTree(data.tree);
  }else{
    const holder=document.querySelector(`[data-children="${cssEscape(path)}"]`);
    if(holder) holder.innerHTML=(data.tree.children||[]).map(renderTree).join("");
  }
 }catch(e){trace.textContent=String(e)}
}

function cssEscape(s){
 return String(s).replace(/["\\]/g,"\\$&");
}

function renderTree(node){
 const icon=node.type==="directory"?"▸":"•";
 const cls=node.type==="directory"?"treeDir":"treeFile";
 const path=node.path||"";
 const safe=path.replaceAll("'","\\'");
 let click=node.type==="file"
   ? `openFile('${safe}')`
   : `toggleDir('${safe}')`;
 let html=`<div class="treeItem ${cls}" onclick="${click}">${icon} ${esc(node.name)}</div>`;
 if(node.type==="directory"){
   html+=`<div data-children="${esc(path)}" style="padding-left:12px">`;
   if(node.children){
     for(const child of node.children)html+=renderTree(child);
   }
   html+=`</div>`;
 }
 return html;
}

async function toggleDir(path){
 const holder=document.querySelector(`[data-children="${cssEscape(path)}"]`);
 if(!holder)return;
 if(holder.dataset.loaded==="1"){
   holder.style.display=holder.style.display==="none"?"block":"none";
   return;
 }
 holder.dataset.loaded="1";
 await loadTree(path);
}

async function openFile(path){currentFile=path;const res=await fetch("/api/file?path="+encodeURIComponent(path));const data=await res.json();if(!data.ok){trace.textContent=data.error||"file failed";return}document.getElementById("editorTitle").textContent=data.file.path+" — "+data.file.size+" chars";document.getElementById("editorContent").textContent=data.file.content;document.getElementById("editorPanel").classList.add("open")}
function closeEditor(){document.getElementById("editorPanel").classList.remove("open")}
async function loadGraph(){try{const res=await fetch("/api/graph");const data=await res.json();const graph=data.graph||{};const canvas=document.getElementById("graphCanvas"),ctx=canvas.getContext("2d");canvas.width=canvas.clientWidth;canvas.height=canvas.clientHeight;ctx.clearRect(0,0,canvas.width,canvas.height);const nodes=(graph.nodes||[]).slice(0,120),pos=[];for(let i=0;i<nodes.length;i++){const a=(i/nodes.length)*Math.PI*2;pos.push({x:canvas.width/2+Math.cos(a)*Math.min(170,canvas.width*.38),y:canvas.height/2+Math.sin(a)*110})}ctx.strokeStyle="#333";for(let i=0;i<Math.min(260,(graph.edges||[]).length);i++){const a=i%Math.max(pos.length,1),b=(i*7)%Math.max(pos.length,1);if(!pos[a]||!pos[b])continue;ctx.beginPath();ctx.moveTo(pos[a].x,pos[a].y);ctx.lineTo(pos[b].x,pos[b].y);ctx.stroke()}for(const p of pos){ctx.fillStyle="#d6b45f";ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill()}}catch(e){trace.textContent=String(e)}}
async function loadTimeline(){try{const res=await fetch("/api/timeline");const data=await res.json();const el=document.getElementById("timeline");el.innerHTML="";for(const row of (data.timeline||[]).slice().reverse().slice(0,35)){const div=document.createElement("div");div.className="timelineItem";div.innerHTML=`<div class="timelineTime">${esc(row.timestamp||"")}</div><div class="timelineText">${esc(row.summary||"")}</div>`;el.appendChild(div)}}catch(e){trace.textContent=String(e)}}
document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();togglePalette(true)}if(e.key==="Escape")togglePalette(false)});
loadPersonaControl();
</script>
</body>
</html>'''


def now():
    return datetime.now(UTC).isoformat()


def send_json(h, payload, code=200):
    data = json.dumps(payload, ensure_ascii=False).encode()
    h.send_response(code)
    h.send_header("Content-Type", "application/json; charset=utf-8")
    h.send_header("Cache-Control", "no-store")
    h.send_header("Content-Length", str(len(data)))
    h.end_headers()
    h.wfile.write(data)


def send_html(h, html, code=200):
    data = html.encode()
    h.send_response(code)
    h.send_header("Content-Type", "text/html; charset=utf-8")
    h.send_header("Cache-Control", "no-store")
    h.send_header("Content-Length", str(len(data)))
    h.end_headers()
    h.wfile.write(data)


def body_json(h):
    n = int(h.headers.get("Content-Length", "0"))
    raw = h.rfile.read(n).decode() if n else "{}"
    try:
        return json.loads(raw)
    except Exception:
        return {}


def run_cmd(args, input_text=None):
    p = subprocess.run(args, cwd=str(ROOT), input=input_text, text=True, capture_output=True, check=False)
    return {"ok": p.returncode == 0, "out": (p.stdout or "") + (("\n[stderr]\n" + p.stderr) if p.stderr else ""), "code": p.returncode}


