class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            parsed = urlparse(self.path)
            path = parsed.path

            if path == "/api/observatory/fields":
                try:
                    import subprocess

                    subprocess.run(
                        [
                            sys.executable,
                            str(ROOT / "runtime" / "palaver" / "graph" / "runtime_graph_engine.py")
                        ],
                        cwd=str(ROOT),
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE,
                        text=True,
                        timeout=30,
                    )

                    subprocess.run(
                        [
                            sys.executable,
                            str(ROOT / "runtime" / "palaver" / "fields" / "structural_fields.py")
