                send_json(self, read_text_payload("vault/quarantine/CLEANUP_LEDGER.md"))
                return

            if path == "/api/quarantine/restore-index":
                send_json(self, read_text_payload("vault/quarantine/RESTORE_INDEX.tsv"))
                return

            if path == "/api/dashboard/state":
                send_json(self, read_json_payload("vault/projections/dashboard/system_dashboard.json"))
                return
            # AUTHORITY_FORCE_ROUTES_END
            q = parse_qs(parsed.query)

            if path == "/":
                send_html(self, HTML)
                return

            if path == "/api/health":
                send_json(self, {"ok": True, "health": health()})
                return

            if path == "/api/routes":
                send_json(self, {
                    "ok": True,
                    "routes": {
                        "get": [
                            "/",
                            "/api/health",
                            "/api/routes",
                            "/api/diagnostics/crash",
                            "/api/tree",
                            "/api/file",
                            "/api/graph",
                            "/api/timeline",
                            "/api/runtime",
                            "/api/repository/files",
                            "/api/memory/files",
                            "/api/memory/search",
                            "/api/agents/jobs"
                        ],
                        "post": [
                            "/api/chat",
                            "/api/file/save",
                            "/api/file/diff",
                            "/api/workspace/save",
                            "/api/patch/write",
                            "/api/patch/append",
                            "/api/patch-review/create",
                            "/api/patch-review/apply",
                            "/api/patch-review/reject"
                        ]
                    }
                })
                return

            if path == "/api/diagnostics/crash":
                base = ROOT / "vault" / "diagnostics" / "crashes"
                files = sorted(base.glob("*.txt")) if base.exists() else []
                if not files:
                    send_json(self, {"ok": True, "crash": None})
                    return
                latest = files[-1]
                send_json(self, {
                    "ok": True,
                    "crash": {
                        "file": str(latest.relative_to(ROOT)),
                        "content": latest.read_text(encoding="utf-8", errors="ignore")[:50000],
                    }
                })
                return

            if path == "/api/tree":
                target = q.get("path", [""])[0]
                base = ROOT / target if target else ROOT
                send_json(self, {"ok": True, "tree": build_file_tree(base)})
                return

            if path == "/api/file":
                target = q.get("path", [""])[0]
                send_json(self, {"ok": True, "file": read_file_payload(target)})
                return

            if path == "/api/graph":
                send_json(self, {"ok": True, "graph": graph_snapshot()})
                return

            if path == "/api/timeline":
                send_json(self, {"ok": True, "timeline": activity_timeline()})
                return

            if path == "/api/runtime":
                send_json(self, {"ok": True, "runtime": runtime_payload()})
                return

            if path == "/api/repository/files":
                send_json(self, {"ok": True, "files": repository_files_payload()})
                return

            if path == "/api/memory/files":
                send_json(self, {"ok": True, "memory": memory_files_payload()})
                return

            if path == "/api/memory/search":
                term = q.get("q", [""])[0].lower().strip()
                rows = []

                roots = [
                    ROOT / "vault" / "web_chats",
                    ROOT / "vault" / "knowledge",
                    ROOT / "vault" / "message_registry",
                ]

                if term:
                    for base in roots:
                        if not base.exists():
                            continue

                        for f in base.glob("*.json"):
                            try:
                                text = f.read_text(encoding="utf-8", errors="ignore")
                            except Exception:
                                continue

                            if term in text.lower():
                                rows.append({
                                    "path": str(f.relative_to(ROOT)),
                                    "preview": text[:500],
                                })

                                if len(rows) >= 50:
                                    break

                        if len(rows) >= 50:
                            break

                send_json(self, {"ok": True, "results": rows})
                return

            if path == "/api/agents/jobs":
                send_json(self, {"ok": True, "jobs": agent_jobs_payload()})
                return


            elif path == "/api/authority/map":
                send_json(self, read_text_payload("vault/graph_address/graph_addresses.latest.tsv"))

            elif path == "/api/authority/relationships":
                send_json(self, read_text_payload("vault/relationships/system_relationships.latest.tsv"))

            elif path == "/api/authority/contracts":
                send_json(self, read_text_payload("vault/contracts/extension_contracts.md"))

            elif path == "/api/authority/palaver":
                send_json(self, latest_matching_payload("vault/authority/registries/palaver_exile_registry_*.json", text=False))

            elif path == "/api/authority/slots":
                send_json(self, read_text_payload("vault/authority/registries/instance_slots.tsv"))

            elif path == "/api/quarantine/ledger":
                send_json(self, read_text_payload("vault/quarantine/CLEANUP_LEDGER.md"))

            elif path == "/api/quarantine/restore-index":
                send_json(self, read_text_payload("vault/quarantine/RESTORE_INDEX.tsv"))

            elif path == "/api/dashboard/state":
                send_json(self, read_json_payload("vault/projections/dashboard/system_dashboard.json"))

            send_json(self, {"ok": False, "error": "not found"}, 404)

        except Exception as e:
            crash = ROOT / "vault" / "diagnostics" / "crashes"
            crash.mkdir(parents=True, exist_ok=True)
            stamp = datetime.now(UTC).strftime("%Y%m%d_%H%M%S_%f")
            tb = traceback.format_exc()
            (crash / f"get_{stamp}.txt").write_text(tb, encoding="utf-8")
            send_json(self, {"ok": False, "error": str(e), "traceback": tb}, 500)

    def do_POST(self):
        try:
            path = urlparse(self.path).path
            data = body_json(self)

            if path == "/api/chat":
                message = data.get("message", "").strip()
                if not message:
                    send_json(self, {"ok": False, "answer": "", "trace": "empty"})
                    return
                send_json(self, {"ok": True, **chat(message)})
                return

            if path == "/api/file/save":
                target = data.get("path", "").strip()
                content = data.get("content", "")
                send_json(self, {"ok": True, "file": save_file_payload(target, content)})
                return

            if path == "/api/file/diff":
                target = data.get("path", "").strip()
                content = data.get("content", "")
                send_json(self, {"ok": True, "diff": diff_payload(target, content)})
                return

            if path == "/api/workspace/save":
                send_json(self, {"ok": True, "result": workspace_state_save(data)})
                return

            if path == "/api/patch/write":
                target = data.get("path", "").strip()
                content = data.get("content", "")
                intent = data.get("intent", "browser write proposal")
                r = run_cmd(["./patch", "write", target, "--stdin", "--intent", intent], input_text=content)
                send_json(self, {"ok": r["ok"], "output": r["out"]})
                return

            if path == "/api/patch/append":
                target = data.get("path", "").strip()
                content = data.get("content", "")
                intent = data.get("intent", "browser append proposal")
                r = run_cmd(["./patch", "append", target, "--stdin", "--intent", intent], input_text=content)
                send_json(self, {"ok": r["ok"], "output": r["out"]})
                return

            if path == "/api/patch-review/create":
                target = data.get("path", "").strip()
                content = data.get("content", "")
                send_json(self, {"ok": True, "patch": patch_review_create_payload(target, content)})
                return

            if path == "/api/patch-review/apply":
                patch_id = data.get("patch_id", "").strip()
                send_json(self, {"ok": True, "patch": patch_review_apply_payload(patch_id)})
                return

            if path == "/api/patch-review/reject":
                patch_id = data.get("patch_id", "").strip()
                send_json(self, {"ok": True, "patch": patch_review_reject_payload(patch_id)})
                return

            send_json(self, {"ok": False, "error": "not found"}, 404)

        except Exception as e:
            crash = ROOT / "vault" / "diagnostics" / "crashes"
            crash.mkdir(parents=True, exist_ok=True)
            stamp = datetime.now(UTC).strftime("%Y%m%d_%H%M%S_%f")
            (crash / f"server_{stamp}.txt").write_text(traceback.format_exc(), encoding="utf-8")
            send_json(self, {"ok": False, "answer": "Server route crashed.", "trace": str(e)}, 500)


